DATA_ACQUISITION_NOTICE_AUTO_DISMISS_SCRIPT = r'''
(() => {
  if (window.__dxmAgentDataAcquisitionNoticeAutoDismissInstalled) return;
  window.__dxmAgentDataAcquisitionNoticeAutoDismissInstalled = true;
  const norm = (s) => String(s || '').replace(/\s+/g, '').trim();
  const isVisible = (el) => {
    if (!el || !el.getBoundingClientRect) return false;
    const r = el.getBoundingClientRect();
    const style = window.getComputedStyle(el);
    return r.width > 0 && r.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const textOf = (el) => (el.innerText || el.textContent || '').replace(/\s+/g, ' ').trim();
  const isNoticeLike = (el, compact) => {
    const cls = String(el.className || '');
    return cls.includes('notice')
      || cls.includes('Notice')
      || cls.includes('activity')
      || cls.includes('Activity')
      || compact.includes('线下活动')
      || compact.includes('小秘公告')
      || compact.includes('活动亮点')
      || compact.includes('公告');
  };
  const hasDangerousMutationText = (compact) => [
    '立即发布',
    '继续发布',
    '保存并发布',
    '确认发布',
    '提交发布',
    '保存并移入待发布',
    '移入待发布',
  ].some(term => compact.includes(norm(term)));
  const closeNotice = () => {
    const selectors = [
      '.notice-list-modal',
      '.ant-modal-wrap',
      '.ant-modal',
      '[role="dialog"]',
      '[class*="notice"]',
      '[class*="Notice"]',
      '[class*="activity"]',
      '[class*="Activity"]'
    ].join(',');
    const modals = Array.from(document.querySelectorAll(selectors))
      .filter(isVisible)
      .map(el => ({el, text: textOf(el), compact: norm(textOf(el))}))
      .filter(item => item.text && isNoticeLike(item.el, item.compact) && !hasDangerousMutationText(item.compact));
    for (const item of modals) {
      const modal = item.el;
      const controls = Array.from(modal.querySelectorAll('.ant-modal-close, .ant-modal-close-x, .close, .close-btn, .notice-close, [class*="close"], [aria-label*="Close"], [aria-label*="关闭"], button, a, span, div'))
        .filter(isVisible)
        .map(el => ({
          el,
          text: norm(el.innerText || el.textContent || el.getAttribute('aria-label') || el.getAttribute('title') || ''),
          cls: String(el.className || ''),
          tag: String(el.tagName || '').toLowerCase(),
        }))
        .filter(item => {
          if (['开始采集', '一键发布', '采集并一键发布', '认领', '批量认领', '保存', '发布'].includes(item.text)) return false;
          return item.text === '关闭'
            || item.text === '知道了'
            || item.text === '我知道了'
            || item.cls.includes('ant-modal-close')
            || item.cls.includes('close')
            || item.cls.includes('Close');
        });
      const target = controls.find(item => item.text === '关闭')
        || controls.find(item => item.cls.includes('ant-modal-close') || item.cls.includes('close') || item.cls.includes('Close'))
        || controls[0];
      if (target) {
        try { target.el.click(); } catch (_) {}
      }
      setTimeout(() => {
        if (document.body.contains(modal) && isVisible(modal)) {
          try { modal.remove(); } catch (_) { modal.style.display = 'none'; }
        }
        document.querySelectorAll('.ant-modal-mask, .modal-backdrop, [class*="modal-mask"]').forEach(mask => {
          if (isVisible(mask)) {
            try { mask.remove(); } catch (_) { mask.style.display = 'none'; }
          }
        });
      }, 200);
    }
  };
  closeNotice();
  const timer = window.setInterval(closeNotice, 500);
  const observer = new MutationObserver(closeNotice);
  const start = () => {
    if (document.documentElement) {
      observer.observe(document.documentElement, {childList: true, subtree: true});
    }
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, {once: true});
  } else {
    start();
  }
  window.setTimeout(() => {
    window.clearInterval(timer);
    observer.disconnect();
  }, 30000);
})();
'''


class DxmLoginFlow:
    def __init__(self, live_client: DxmLiveClient, state_file: Path | None = None) -> None:
        self.live_client = live_client
        self.state_file = state_file or RUNTIME_STATE_FILE
        self._playwright: Playwright | None = None
        self._browser: Browser | None = None
        self._context: BrowserContext | None = None
        self._page: Page | None = None
        self._browser_session_thread_id: int | None = None
        self._latest_live_hud: dict[str, Any] | None = None
        self._live_hud_reapply_pending = False
        self._live_hud_bound_page_ids: set[int] = set()
        self._live_hud_bound_context_ids: set[int] = set()
        self._data_acquisition_notice_bound_context_ids: set[int] = set()
        self._last_dismiss_blocking_modals_trace: list[dict[str, Any]] = []
        self._recent_workflow_events: list[dict[str, Any]] = []
        self._workflow_event_listener: Callable[[dict[str, Any]], None] | None = None
        self._remote_debugging_port: int | None = None
        self._external_browser_process: subprocess.Popen | None = None
        self._mutation_authorizer: Callable[[dict[str, Any], Callable[[], Any]], Any] | None = None
        self._mutation_command_context: dict[str, Any] | None = None
        self._last_mutation_authorization_facts: dict[str, Any] | None = None
        self._execution_evidence_context: dict[str, Any] | None = None
        self._browser_session_generation: str | None = None
        self._browser_session_context_id: int | None = None
        self._browser_session_browser_id: int | None = None
        self._browser_session_hooked_context_ids: set[int] = set()
        self._browser_session_hooked_browser_ids: set[int] = set()

    def set_mutation_authorizer(
        self,
        authorizer: Callable[[dict[str, Any], Callable[[], Any]], Any] | None,
        command_context: dict[str, Any] | None = None,
    ) -> None:
        self._mutation_authorizer = authorizer if callable(authorizer) else None
        self._mutation_command_context = dict(command_context or {}) if self._mutation_authorizer else None

    def clear_mutation_authorizer(self) -> None:
        self._mutation_authorizer = None
        self._mutation_command_context = None

    def set_execution_evidence_context(self, context: dict[str, Any] | None) -> None:
        self._execution_evidence_context = dict(context or {}) if isinstance(context, dict) else None

    def clear_execution_evidence_context(self) -> None:
        self._execution_evidence_context = None

    @staticmethod
    def _safe_evidence_file_part(value: Any) -> str:
        text = str(value or '').strip()
        safe = ''.join(character if character.isalnum() or character in {'-', '_'} else '_' for character in text)
        return safe[:80]

    def _scoped_evidence_path(self, base_path: Path, *, action: str) -> Path:
        context = self._execution_evidence_context if isinstance(self._execution_evidence_context, dict) else {}
        parts = {
            key: self._safe_evidence_file_part(context.get(key))
            for key in ('task_id', 'job_id', 'state', 'command_id')
        }
        if not all(parts.values()):
            raise RuntimeError('EVIDENCE_CONTEXT_MISSING: 证据缺少 task/job/state/command 唯一上下文')
        action_part = self._safe_evidence_file_part(action)
        target = Path(base_path).resolve().with_name(
            f"{Path(base_path).stem}_task_{parts['task_id']}_job_{parts['job_id']}_{parts['state']}_{parts['command_id']}_{action_part}{Path(base_path).suffix}"
        )
        target.parent.mkdir(parents=True, exist_ok=True)
        return target

    @staticmethod
    def _evidence_descriptor(path: Path) -> dict[str, Any]:
        resolved = Path(path).resolve()
        if not resolved.is_file():
            raise RuntimeError(f'EVIDENCE_FILE_MISSING: {resolved}')
        content = resolved.read_bytes()
        if not content:
            raise RuntimeError(f'EVIDENCE_FILE_EMPTY: {resolved}')
        return {
            'path': str(resolved),
            'sha256': hashlib.sha256(content).hexdigest().upper(),
            'size': len(content),
        }

    def _capture_scoped_evidence_screenshot(
        self,
        page: Page,
        base_path: Path,
        *,
        action: str,
        full_page: bool,
    ) -> dict[str, Any]:
        target = self._scoped_evidence_path(base_path, action=action)
        try:
            descriptor = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL)
        except FileExistsError as exc:
            raise RuntimeError(f'EVIDENCE_PATH_ALREADY_EXISTS: {target}') from exc
        temporary = target.with_name(f'.{target.stem}.{uuid.uuid4().hex}.tmp{target.suffix}')
        try:
            page.screenshot(path=str(temporary), full_page=full_page)
            content = temporary.read_bytes()
            if not content:
                raise RuntimeError(f'EVIDENCE_FILE_EMPTY: {temporary}')
            offset = 0
            while offset < len(content):
                offset += os.write(descriptor, content[offset:])
            os.fsync(descriptor)
        except Exception:
            os.close(descriptor)
            descriptor = -1
            try:
                target.unlink(missing_ok=True)
            except Exception:
                pass
            raise
        finally:
            if descriptor >= 0:
                os.close(descriptor)
            try:
                temporary.unlink(missing_ok=True)
            except Exception:
                pass
        return self._evidence_descriptor(target)

    def _dispatch_authorized_mutation(
        self,
        mutation_action: str,
        operation: Callable[[], Any],
        *,
        pre_dispatch_guard: Callable[[], Any] | None = None,
    ) -> dict[str, Any]:
        authorizer = self._mutation_authorizer
        if authorizer is None:
            raise MutationAuthorizationError('AUTH_VERIFIER_MISSING: 真实写入点击缺少即时授权校验器')
        if not callable(operation):
            raise MutationAuthorizationError('MUTATION_OPERATION_INVALID: 真实写入 operation 不可调用')
        context = {
            **dict(self._mutation_command_context or {}),
            'mutation_action': str(mutation_action),
            '_pre_dispatch_guard': pre_dispatch_guard,
        }
        operation_attempts = 0
        operation_result: Any = None
        operation_error: Exception | None = None

        def guarded_operation() -> Any:
            nonlocal operation_attempts, operation_result, operation_error
            operation_attempts += 1
            if operation_attempts != 1:
                raise MutationAuthorizationError(
                    'MUTATION_OPERATION_MULTIPLE_EXECUTIONS: 同一授权 operation 禁止重复执行'
                )
            try:
                operation_result = operation()
            except Exception as exc:
                operation_error = exc
                raise
            return operation_result

        try:
            result = authorizer(context, guarded_operation)
        except Exception as exc:
            if isinstance(exc, MutationAuthorizationError):
                raise
            explicit_code = _MUTATION_FAILURE_CODE_PATTERN.match(str(exc).strip())
            reason_code = str(
                getattr(exc, 'reason_code', None)
                or getattr(exc, 'error_code', None)
                or (explicit_code.group(1) if explicit_code else None)
                or ('MUTATION_OPERATION_FAILED' if operation_attempts else 'AUTH_REVALIDATION_FAILED')
            )
            raise MutationAuthorizationError(f'{reason_code}: {exc}') from exc
        if operation_error is not None:
            raise MutationAuthorizationError(f'MUTATION_OPERATION_FAILED: {operation_error}') from operation_error
        if not isinstance(result, Mapping) or result.get('ok') is not True:
            reason_code = (
                str(result.get('reason_code') or 'AUTH_REVALIDATION_FAILED')
                if isinstance(result, Mapping)
                else 'AUTH_REVALIDATION_FAILED'
            )
            raise MutationAuthorizationError(f'{reason_code}: 真实写入点击授权已失效')
        if operation_attempts != 1:
            reason_code = (
                'MUTATION_OPERATION_MULTIPLE_EXECUTIONS'
                if operation_attempts > 1
                else 'MUTATION_OPERATION_NOT_EXECUTED'
            )
            raise MutationAuthorizationError(f'{reason_code}: 授权回调没有 exactly-once 执行真实写入 operation')
        if result.get('executed') is not True:
            raise MutationAuthorizationError(
                'MUTATION_OPERATION_NOT_EXECUTED: 授权结果没有确认 operation 已执行'
            )
        if 'operation_result' not in result:
            raise MutationAuthorizationError(
                'MUTATION_OPERATION_RESULT_MISSING: 授权结果缺少 operation_result'
            )
        authorization_facts = {
            key: value
            for key, value in dict(result).items()
            if key != 'operation_result'
        }
        authorization_facts = {
            **authorization_facts,
            'ok': True,
            'executed': True,
            'mutation_action': str(mutation_action),
        }
        self._last_mutation_authorization_facts = dict(authorization_facts)
        return {
            **dict(result),
            'ok': True,
            'executed': True,
            'mutation_action': str(mutation_action),
            'operation_result': operation_result,
            'authorization_facts': dict(authorization_facts),
        }

    @staticmethod
    def _run_mutation_pre_dispatch_guard(
        guard: Callable[[], Any] | None,
    ) -> None:
        if not callable(guard):
            return
        result = guard()
        rejected = result is False or (
            isinstance(result, Mapping) and result.get('ok') is not True
        )
        if rejected:
            reason = (
                str(result.get('reason') or 'live mutation target changed')
                if isinstance(result, Mapping)
                else 'live mutation target changed'
            )
            raise MutationAuthorizationError(
                f'MUTATION_TARGET_DRIFT: {reason}'
            )

    def _bind_browser_context_generation(self, context: BrowserContext) -> str:
        browser = self._browser
        if (
            context is not self._context
            or browser is None
            or not callable(getattr(context, 'is_closed', None))
            or not callable(getattr(browser, 'is_connected', None))
            or self._is_playwright_object_closed(context)
            or not self._is_browser_connected(browser)
        ):
            self._clear_browser_context_generation()
            raise RuntimeError(
                'BROWSER_SESSION_OBJECT_INACTIVE: browser context must be current, open, and connected'
            )
        context_id = id(context)
        browser_id = id(browser)
        if (
            self._browser_session_context_id != context_id
            or self._browser_session_browser_id != browser_id
            or not self._browser_session_generation
        ):
            self._browser_session_generation = uuid.uuid4().hex
            self._browser_session_context_id = context_id
            self._browser_session_browser_id = browser_id
        if context_id not in self._browser_session_hooked_context_ids:
            on_context = getattr(context, 'on', None)
            if callable(on_context):
                try:
                    on_context('close', lambda *_args, bound=context: self._on_browser_context_closed(bound))
                    self._browser_session_hooked_context_ids.add(context_id)
                except Exception:
                    pass
        if id(browser) not in self._browser_session_hooked_browser_ids:
            on_browser = getattr(browser, 'on', None)
            if callable(on_browser):
                try:
                    on_browser('disconnected', lambda *_args, bound=browser: self._on_browser_disconnected(bound))
                    self._browser_session_hooked_browser_ids.add(id(browser))
                except Exception:
                    pass
        return self._browser_session_generation

    def _on_browser_context_closed(self, context: BrowserContext) -> None:
        self._browser_session_hooked_context_ids.discard(id(context))
        if self._browser_session_context_id == id(context):
            self._clear_browser_context_generation()

    def _on_browser_disconnected(self, browser: Browser) -> None:
        self._browser_session_hooked_browser_ids.discard(id(browser))
        if self._browser_session_browser_id == id(browser):
            self._clear_browser_context_generation()

    def _clear_browser_context_generation(self) -> None:
        self._browser_session_generation = None
        self._browser_session_context_id = None
        self._browser_session_browser_id = None

    def browser_session_id(self) -> str | None:
        if self._browser_session_context_id is None or self._browser_session_browser_id is None:
            return None
        value = str(self._browser_session_generation or '').strip()
        return value or None

    def current_mutation_identity(self) -> dict[str, Any] | None:
        """Return the live browser/page and command-target binding for dispatch.

        This method runs on the Browser Agent thread, so reading the current
        Playwright page is safe. The target hash is recomputed from task-bound
        values; claim/save click primitives separately revalidate the DOM target
        immediately before emitting their input event.
        """

        context = self._mutation_command_context
        page = self._page
        if not isinstance(context, dict) or page is None:
            return None
        page_url = str(getattr(page, 'url', '') or '').strip()
        expected_page = str(context.get('expected_page') or '').strip()
        if not page_url or not expected_page:
            return None
        identity_result = self._page_identity_result(page_url, expected_page)
        if identity_result.get('ok') is not True:
            return {
                'browser_session_id': self.browser_session_id(),
                'page_url': page_url,
                'page_kind': None,
                'target_hash': None,
            }
        command_action = str(context.get('command_action') or '').strip()
        target_values = context.get('mutation_target')
        if not command_action or not isinstance(target_values, dict):
            return None
        try:
            observed_values = dict(target_values)
            frozen_target = observed_values.get('target_identity')
            if frozen_target is not None:
                normalized_target, _target_sha256 = self._normalize_frozen_target_identity(
                    frozen_target,
                    store_name=observed_values.get('store_name'),
                    target_source_urls=observed_values.get('target_source_urls'),
                )
                # The authorization hash is a live target observation, not a
                # hash of trusted command parameters.  Frozen saves are only
                # dispatchable from the exact structured editor readback.
                if expected_page not in {'editor', 'semi_managed'}:
                    raise FrozenTargetIdentityError(
                        'FROZEN_TARGET_LIVE_PRODUCT_PAGE_REQUIRED',
                        '冻结商品保存授权要求当前精确商品编辑页。',
                    )
                live_match = self._editor_page_matches_frozen_target(
                    page,
                    target_identity=normalized_target,
                    store_name=observed_values.get('store_name'),
                )
                if live_match.get('ok') is not True:
                    raise FrozenTargetIdentityError(
                        'FROZEN_TARGET_LIVE_READBACK_MISMATCH',
                        '冻结商品保存授权前的实时身份读回不一致。',
                    )
                observed_values['target_identity'] = normalized_target
            observed_target_hash = mutation_target_hash(command_action, observed_values)
        except Exception:
            observed_target_hash = None
        return {
            'browser_session_id': self.browser_session_id(),
            'page_url': page_url,
            'page_kind': expected_page,
            'target_hash': observed_target_hash,
        }

    def set_workflow_event_listener(self, listener: Callable[[dict[str, Any]], None] | None) -> None:
        self._workflow_event_listener = listener if callable(listener) else None

    def recent_workflow_events(self, limit: int = 20) -> list[dict[str, Any]]:
        if limit <= 0:
            return []
        return list(self._recent_workflow_events[-limit:])

    def get_state(self) -> dict[str, Any]:
        if self.state_file.exists():
            state = json.loads(self.state_file.read_text(encoding='utf-8'))
            if (
                state.get('logged_in') is True
                and state.get('reader_ready') is True
                and self.browser_session_id() is None
            ):
                return {
                    **state,
                    'ok': False,
                    'stage': 'session_unavailable',
                    'reason_code': 'BROWSER_SESSION_UNAVAILABLE',
                    'logged_in': False,
                    'reader_ready': False,
                    'browser_session_id': None,
                    'account_ref': None,
                    'message': '上一次登录证明属于旧进程；当前 Playwright 可见会话尚未建立。',
                    'next_action': '从工作台重新连接店小秘；持久化 profile 可复用，但必须由当前进程重新证明。',
                    'requires_user_action': True,
                    'updated_at': now_iso(),
                }
            return state
        return self._default_state()

    def get_live_state(self) -> dict[str, Any]:
        """Return a Reader-usable state from the visible-session owner thread.

        The persisted login result is only a claim.  A disconnected CDP browser
        can keep that claim green until Playwright processes its next command,
        so live-status must verify the exact session object used by Reader.
        This method is intentionally cheap and performs no navigation or DXM
        request; callers dispatch it through the single visible-session owner.
        """

        if self.state_file.exists():
            state = json.loads(self.state_file.read_text(encoding='utf-8'))
        else:
            state = self._default_state()
        if state.get('logged_in') is not True or state.get('reader_ready') is not True:
            page = self._promote_dxm_page_from_connected_browser()
            if page is not None and self._page_looks_logged_in(page):
                reader_status = self._visible_reader_session_status()
                if reader_status.get('reader_ready') is True:
                    verified = {
                        **state,
                        'ok': True,
                        'stage': 'login_success',
                        'reason_code': 'LOGIN_READER_READY',
                        'logged_in': True,
                        'reader_ready': True,
                        'browser_session_id': reader_status.get('browser_session_id'),
                        'account_ref': reader_status.get('account_ref'),
                        'page_url': str(getattr(page, 'url', '') or ''),
                        'message': '登录成功，当前真实可见浏览器已可直接读取店铺与草稿。',
                        'next_action': '返回工作台进入采集箱选品；本阶段不会保存或发布。',
                        'requires_user_action': False,
                        'updated_at': now_iso(),
                    }
                    self._write_state(verified)
                    return verified
            return state
        try:
            page, _context, browser_session_id = self._draft_reader_session()
        except DxmDraftReaderError as exc:
            revoked = {
                **state,
                'ok': False,
                'stage': 'session_unavailable',
                'reason_code': str(exc.reason_code or 'BROWSER_SESSION_UNAVAILABLE'),
                'logged_in': False,
                'reader_ready': False,
                'browser_session_id': None,
                'account_ref': None,
                'message': str(exc),
                'next_action': '从工作台重新连接店小秘；登录成功后 Reader 会复用同一个真实可见会话。',
                'requires_user_action': True,
                'updated_at': now_iso(),
            }
            self._write_state(revoked)
            return revoked
        verified = {
            **state,
            'ok': True,
            'stage': 'login_success',
            'reason_code': 'LOGIN_READER_READY',
            'logged_in': True,
            'reader_ready': True,
            'browser_session_id': browser_session_id,
            'page_url': str(getattr(page, 'url', '') or state.get('page_url') or ''),
            'requires_user_action': False,
            'updated_at': now_iso(),
        }
        if verified != state:
            self._write_state(verified)
        return verified

    def update_live_hud(self, hud: dict[str, Any]) -> dict[str, Any]:
        self._latest_live_hud = dict(hud)
        page = self._page
        if page is None:
            return {'ok': True, 'updated': False, 'reason': 'live_browser_page_missing'}
        try:
            return self._apply_live_hud(page, hud)
        except Exception as exc:
            return {
                'ok': False,
                'updated': False,
                'reason': 'live_browser_hud_apply_failed',
                'error': str(exc),
            }

    def _apply_live_hud(self, page: Page, hud: dict[str, Any]) -> dict[str, Any]:
        self._attach_live_hud_runtime_hooks(page)
        try:
            page.add_init_script(HUD_INIT_SCRIPT)
        except Exception:
            pass
        try:
            self._evaluate_zero_arg_page_function_with_runtime_timeout(
                page,
                f"() => {{\n{HUD_INIT_SCRIPT}\nreturn true;\n}}",
                timeout=750,
            )
        except Exception:
            pass
        self._evaluate_page_function_with_runtime_timeout(
            page,
            """
            (hud) => {
              window.__dxmAgentHudState = hud;
              try {
                window.sessionStorage.setItem('__dxmAgentHudPersistedState', JSON.stringify(hud));
              } catch (error) {}
              try {
                window.localStorage.setItem('__dxmAgentHudPersistedState', JSON.stringify(hud));
              } catch (error) {}
              if (window.__dxmRenderAgentHud) window.__dxmRenderAgentHud();
            }
            """,
            hud,
            timeout=750,
        )
        self._live_hud_reapply_pending = False
        return {
            'ok': True,
            'updated': True,
            'reason': 'live_browser_hud_updated',
            'hud': hud,
            'page_title': self._safe_live_hud_page_title(page),
            'current_url': page.url,
            'updated_at': now_iso(),
        }

    def _safe_live_hud_page_title(self, page: Page) -> str:
        try:
            title = self._evaluate_zero_arg_page_function_with_runtime_timeout(
                page,
                "() => document.title || ''",
                timeout=500,
            )
            return str(title or '')
        except Exception:
            return ''

    def _mark_live_hud_reapply_pending(self, *_args) -> None:
        self._live_hud_reapply_pending = True

    def _trace_workflow_event(self, event: str, **payload: Any) -> None:
        record = {
            'ts': now_iso(),
            'event': event,
            **payload,
        }
        if not record.get('human_step'):
            record['human_step'] = WORKFLOW_HUMAN_STEP_COPY.get(event) or event
        self._recent_workflow_events.append(record)
        del self._recent_workflow_events[:-400]
        listener = self._workflow_event_listener
        if listener:
            try:
                listener(dict(record))
            except Exception:
                pass
        trace_file = os.getenv('DXM_WORKFLOW_TRACE_FILE')
        if not trace_file:
            return
        try:
            path = Path(trace_file)
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open('a', encoding='utf-8') as fh:
                fh.write(json.dumps(record, ensure_ascii=False, default=str) + '\n')
        except Exception:
            pass

    def _attach_live_hud_runtime_hooks(self, page: Page | None) -> None:
        if page is None:
            return
        page_id = id(page)
        if page_id not in self._live_hud_bound_page_ids:
            self._live_hud_bound_page_ids.add(page_id)
            try:
                page.add_init_script(HUD_INIT_SCRIPT)
            except Exception:
                pass
            for event_name in ('framenavigated', 'domcontentloaded'):
                try:
                    page.on(event_name, self._mark_live_hud_reapply_pending)
                except Exception:
                    pass

        context = getattr(page, 'context', None)
        if context is None:
            return
        context_id = id(context)
        if context_id in self._live_hud_bound_context_ids:
            return
        self._live_hud_bound_context_ids.add(context_id)
        try:
            context.add_init_script(HUD_INIT_SCRIPT)
        except Exception:
            pass
        try:
            context.on('page', self._mark_live_hud_reapply_pending)
        except Exception:
            pass

    def _attach_and_reapply_live_hud_page(self, page: Page) -> None:
        self._attach_live_hud_runtime_hooks(page)
        self._reapply_live_hud_if_available(page)

    def _reapply_live_hud_if_available(self, page: Page) -> None:
        if not self._latest_live_hud:
            return
        try:
            self._apply_live_hud(page, self._latest_live_hud)
            self._live_hud_reapply_pending = False
        except Exception:
            pass

    def _goto_with_live_hud(self, page: Page, url: str, *, wait_until: str = 'domcontentloaded', timeout: int = 45000) -> None:
        self._trace_workflow_event('goto:start', url=url, current_url=getattr(page, 'url', None), wait_until=wait_until, timeout=timeout)
        self._attach_live_hud_runtime_hooks(page)
        self._trace_workflow_event('goto:attached_hud', url=url, current_url=getattr(page, 'url', None))
        page.goto(url, wait_until=wait_until, timeout=timeout)
        self._trace_workflow_event('goto:finished', url=url, current_url=page.url)
        self._reapply_live_hud_if_available(page)
        self._trace_workflow_event('goto:reapplied_hud', url=url, current_url=page.url)

    def _goto_sterile(self, page: Page, url: str, *, wait_until: str = 'domcontentloaded', timeout: int = 45000) -> None:
        self._trace_workflow_event('goto:sterile_start', url=url, current_url=getattr(page, 'url', None), wait_until=wait_until, timeout=timeout)
        page.goto(url, wait_until=wait_until, timeout=timeout)
        self._trace_workflow_event('goto:sterile_finished', url=url, current_url=page.url)

    def _goto_data_acquisition_sterile(self, page: Page, url: str, *, wait_until: str = 'domcontentloaded', timeout: int = 45000) -> None:
        self._trace_workflow_event(
            'data_acquisition_open:sterile_goto_start',
            url=url,
            current_url=getattr(page, 'url', None),
            wait_until=wait_until,
            timeout=timeout,
            human_step='打开已有待认领列表',
        )
        page.goto(url, wait_until=wait_until, timeout=timeout)
        self._trace_workflow_event(
            'data_acquisition_open:sterile_goto_finished',
            url=url,
            current_url=getattr(page, 'url', None),
            human_step='已有待认领列表已打开',
        )
        self._trace_workflow_event(
            'data_acquisition_open:sterile_settle',
            seconds=3.0,
            human_step='等待页面自行加载',
        )
        time.sleep(3.0)

    def _is_current_page_url(self, page: Page, url: str) -> bool:
        try:
            current = urlparse(str(getattr(page, 'url', '') or ''))
            target = urlparse(url)
        except Exception:
            return False
        return (
            bool(current.netloc)
            and current.netloc.casefold() == target.netloc.casefold()
            and current.path.rstrip('/') == target.path.rstrip('/')
        )

    def _page_looks_like_login(self, page: Page) -> bool:
        title = ''
        try:
            title_method = getattr(page, 'title', None)
            if callable(title_method):
                title = str(title_method() or '')
        except Exception:
            title = ''
        url = str(getattr(page, 'url', '') or '')
        normalized = f'{title}\n{url}'.casefold()
        return (
            '登录' in normalized
            or '登陆' in normalized
            or 'login' in normalized
            or '/login' in normalized
        )

    def _page_identity_result(self, page_url: str | None, expected_identity: str) -> dict[str, Any]:
        identity = WORKFLOW_PAGE_IDENTITIES.get(expected_identity)
        if not identity:
            return {
                'ok': False,
                'reason': 'unknown_expected_identity',
                'expected_identity': expected_identity,
                'page_url': str(page_url or ''),
            }
        try:
            parsed = urlparse(str(page_url or ''))
        except ValueError:
            parsed = urlparse('')
        expected_path = str(identity['path']).rstrip('/')
        actual_path = str(parsed.path or '').rstrip('/')
        host_ok = str(parsed.hostname or '').casefold() in {'dianxiaomi.com', 'www.dianxiaomi.com'}
        path_ok = actual_path == expected_path
        query = parse_qs(parsed.query)
        expected_query = identity.get('query') or {}
        query_ok = all((query.get(key) or [''])[0] == value for key, value in expected_query.items())
        required_query_keys = tuple(identity.get('required_query_keys') or ())
        required_query_ok = all(bool((query.get(key) or [''])[0]) for key in required_query_keys)
        return {
            'ok': bool(host_ok and path_ok and query_ok and required_query_ok),
            'reason': 'identity_match' if host_ok and path_ok and query_ok and required_query_ok else 'wrong_route',
            'expected_identity': expected_identity,
            'expected_path': expected_path,
            'actual_path': actual_path,
            'page_url': str(page_url or ''),
        }

    def _browser_readiness_gate(
        self,
        page: Page,
        *,
        label: str,
        expected_identity: str,
        ready_terms: list[str] | tuple[str, ...] | None = None,
    ) -> dict[str, Any]:
        page_title = None
        try:
            title_method = getattr(page, 'title', None)
            if callable(title_method):
                page_title = str(title_method() or '')
        except Exception:
            page_title = None
        page_url = str(getattr(page, 'url', '') or '')
        if self._page_looks_like_login(page):
            return {
                'ok': False,
                'reason': 'login_required',
                'label': label,
                'requires_user_action': True,
                'page_title': page_title,
                'page_url': page_url,
                'message': f'{label}页面显示为登录页，请重新登录店小秘后重试。',
            }
        identity_result = self._page_identity_result(page_url, expected_identity)
        if identity_result.get('ok') is not True:
            return {
                **identity_result,
                'ok': False,
                'reason': identity_result.get('reason') or 'wrong_route',
                'label': label,
                'requires_user_action': True,
                'page_title': page_title,
                'page_url': page_url,
                'message': f'{label}页面路由与期望页面不一致，已停止自动操作。',
            }
        state: dict[str, Any] = {
            'readyState': None,
            'loading': None,
            'loadingCount': None,
            'blockingModal': None,
            'businessMarker': None,
            'businessMarkerCount': 0,
            'bodyExcerpt': '',
        }
        terms = [str(term) for term in (ready_terms or []) if str(term).strip()]
        try:
            evaluate = getattr(page, 'evaluate', None)
            if callable(evaluate):
                probed = evaluate(r'''(terms) => {
                  const textOf = (el) => (el?.innerText || el?.textContent || '').replace(/\s+/g, ' ').trim();
                  const visible = (el) => {
                    if (!el) return false;
                    const r = el.getBoundingClientRect();
                    const s = window.getComputedStyle(el);
                    return r.width > 0 && r.height > 0 && s.display !== 'none' && s.visibility !== 'hidden';
                  };
                  const loadingNodes = Array.from(document.querySelectorAll('.ant-spin-spinning, .vxe-loading, .vxe-loading--wrapper, .el-loading-mask, .ant-spin, .loading, [class*=loading], [class*=Loading]')).filter(visible);
                  const modals = Array.from(document.querySelectorAll('.ant-modal, .ant-modal-wrap, [role=dialog], .ant-drawer')).filter(visible);
                  const markerNodes = Array.from(document.querySelectorAll(
                    'table thead th, .vxe-header--column, .ant-table-thead th, form label, input[placeholder], textarea[placeholder], button, [role=button], [role=tab], h1, h2, h3, .ant-tabs-tab, .el-tabs__item'
                  )).filter(visible);
                  const markerMatches = markerNodes
                    .map(el => textOf(el) || String(el.getAttribute('placeholder') || '').trim())
                    .filter(text => text && terms.some(term => text.includes(term)));
                  return {
                    readyState: document.readyState,
                    loading: loadingNodes.length > 0,
                    loadingCount: loadingNodes.length,
                    blockingModal: modals.length ? textOf(modals[0]).slice(0, 240) : null,
                    businessMarker: markerMatches[0] || null,
                    businessMarkerCount: markerMatches.length,
                    bodyExcerpt: markerMatches.slice(0, 8).join(' | ').slice(0, 500),
                  };
                }''', terms)
                if isinstance(probed, dict):
                    state.update(probed)
        except Exception as exc:
            return {
                'ok': False,
                'reason': 'page_probe_failed',
                'label': label,
                'requires_user_action': True,
                'page_title': page_title,
                'page_url': page_url,
                'error': str(exc)[:240],
                'message': f'{label}页面状态检查无响应，请人工查看真实浏览器。',
            }
        if state.get('loading'):
            return {
                'ok': False,
                'reason': 'page_loading',
                'label': label,
                'requires_user_action': True,
                'page_title': page_title,
                'page_url': page_url,
                'loading': True,
                'loading_count': state.get('loadingCount'),
                'body_excerpt': state.get('bodyExcerpt'),
                'message': f'{label}页面仍在加载，已停止自动操作并保留真实浏览器。',
            }
        if state.get('blockingModal'):
            return {
                'ok': False,
                'reason': 'blocking_modal',
                'label': label,
                'requires_user_action': True,
                'page_title': page_title,
                'page_url': page_url,
                'blocking_modal': state.get('blockingModal'),
                'message': f'{label}页面有弹窗或遮罩阻断，请人工处理后重试。',
            }
        body_excerpt = str(state.get('bodyExcerpt') or '')
        business_marker = str(state.get('businessMarker') or '').strip()
        if not business_marker:
            return {
                'ok': False,
                'reason': 'target_not_ready',
                'label': label,
                'requires_user_action': True,
                'page_title': page_title,
                'page_url': page_url,
                'body_excerpt': body_excerpt,
                'expected_identity': expected_identity,
                'business_marker': None,
                'message': f'{label}页面没有出现目标页面关键内容，请人工确认页面是否打开正确。',
            }
        return {
            'ok': True,
            'reason': 'ready',
            'label': label,
            'requires_user_action': False,
            'page_title': page_title,
            'page_url': page_url,
            'expected_identity': expected_identity,
            'business_marker': business_marker,
            'business_marker_count': state.get('businessMarkerCount'),
            'ready_state': state.get('readyState'),
            'loading': False,
            'blocking_modal': None,
        }

    def start_login(self, username: str, password: str) -> dict[str, Any]:
        opening_state = {
            'ok': False,
            'stage': 'opening_login_page',
            'reason_code': 'LOGIN_OPENING',
            'logged_in': False,
            'reader_ready': False,
            'label': '正在打开真实登录页',
            'message': '正在复用唯一可见 Playwright 会话并填写登录信息。',
            'next_action': '等待真实窗口进入验证码步骤；本操作不会保存或发布。',
            'requires_user_action': False,
            'page_title': '店小秘官网登录页',
            'page_url': 'https://www.dianxiaomi.com/',
            'screenshot_url': None,
            'browser_visible': not self._is_headless(),
            'updated_at': now_iso(),
        }
        self._write_state(opening_state)
        try:
            browser_state = self._open_login_page_and_fill(username, password)
        except Exception as exc:
            self._discard_incomplete_browser_session()
            state = self._error_state(
                stage='login_failed',
                label='打开失败',
                message=f'打开店小秘官网并填写账号密码失败：{exc}',
                next_action='检查本机 Chrome、网络或页面结构后重试。',
                reason_code='LOGIN_BROWSER_START_FAILED',
            )
            self._keep_visible_browser_for_recovery(state)
            self._write_state(state)
            return state
        if browser_state.get('visible_logged_in') is True:
            state = self._login_success_state_from_submit(browser_state)
            self._write_state(state)
            return state
        state = {
            'ok': False,
            'stage': 'waiting_captcha',
            'reason_code': 'LOGIN_INTERACTION_REQUIRED',
            'logged_in': False,
            'reader_ready': False,
            'label': '等待验证码',
            'message': '账号密码已填写，等待用户输入验证码。',
            'next_action': '用户完成验证码后，点击继续登录。',
            'requires_user_action': True,
            'page_title': browser_state.get('page_title') or '店小秘官网登录页',
            'page_url': browser_state.get('page_url') or 'https://www.dianxiaomi.com/',
            'screenshot_url': browser_state.get('screenshot_url'),
            'browser_visible': browser_state.get('browser_visible') is True,
            'updated_at': now_iso(),
            'username': username,
            'password_mask': self._mask_secret(password),
        }
        self._write_state(state)
        return state

    def continue_login(self) -> dict[str, Any]:
        try:
            submit_state = self._submit_login_after_captcha()
        except Exception as exc:
            state = self._error_state(
                stage='login_failed',
                label='继续失败',
                message=f'继续登录失败：{exc}',
                next_action='真实浏览器窗口会保留；请确认验证码是否完成，必要时在窗口内修正后再次检测，或重新打开官网登录页。',
                reason_code='LOGIN_CONTINUE_FAILED',
            )
            state['browser_visible'] = not self._is_headless()
            self._write_state(state)
            return state
        if not self._submit_state_looks_logged_in(submit_state):
            state = {
                'ok': False,
                'stage': 'login_failed',
                'reason_code': 'LOGIN_REQUIRED',
                'logged_in': False,
                'reader_ready': False,
                'label': '登录失败',
                'message': '继续登录后仍未检测到有效登录态，请检查验证码、账号密码或页面结构变化。',
                'next_action': '真实浏览器窗口会保留；请在窗口内修正验证码或账号密码后，再点击检测登录态。',
                'requires_user_action': True,
                'page_title': submit_state.get('page_title') or '店小秘官网登录页',
                'page_url': submit_state.get('page_url') or 'https://www.dianxiaomi.com/',
                'screenshot_url': submit_state.get('screenshot_url'),
                'browser_visible': not self._is_headless(),
                'updated_at': now_iso(),
            }
            self._write_state(state)
            return state
        state = self._login_success_state_from_submit(submit_state)
        self._write_state(state)
        return state

    def probe_visible_session(self) -> dict[str, Any]:
        """Prove the current Playwright session without creating or navigating a page."""

        page = self._page
        page_url = str(getattr(page, 'url', '') or '') if page is not None else ''
        try:
            _page, context, browser_session_id = self._draft_reader_session()
            _payload, account_ref = self._read_authenticated_user_info(
                context,
                browser_session_id,
            )
        except DxmDraftReaderError as exc:
            reason_code = str(exc.reason_code or 'BROWSER_SESSION_UNAVAILABLE')
            stage = 'login_required' if reason_code == 'LOGIN_REQUIRED' else 'session_unavailable'
            state = {
                'ok': False,
                'stage': stage,
                'reason_code': reason_code,
                'logged_in': False,
                'reader_ready': False,
                'label': '真实会话未就绪',
                'message': str(exc),
                'next_action': '从工作台连接店小秘；完成登录后再读取店铺与草稿。',
                'requires_user_action': True,
                'page_title': '店小秘可见会话',
                'page_url': page_url or 'about:blank',
                'screenshot_url': None,
                'browser_visible': not self._is_headless(),
                'updated_at': now_iso(),
            }
            self._write_state(state)
            return state
        except Exception as exc:
            state = self._error_state(
                stage='session_unavailable',
                label='真实会话检查失败',
                message=f'当前 Playwright 可见会话无法完成只读认证检查：{exc}',
                next_action='保留当前窗口并重试；不要另开第二套登录脚本。',
                reason_code='VISIBLE_SESSION_CHECK_FAILED',
            )
            state.update({
                'logged_in': False,
                'reader_ready': False,
                'page_url': page_url or 'about:blank',
                'browser_visible': not self._is_headless(),
            })
            self._write_state(state)
            return state

        state = {
            'ok': True,
            'stage': 'login_success',
            'reason_code': 'LOGIN_READER_READY',
            'logged_in': True,
            'reader_ready': True,
            'label': '已登录且 Reader 就绪',
            'message': '当前 Playwright 可见会话已通过账号只读接口校验。',
            'next_action': '进入采集箱选品；本阶段不会保存或发布。',
            'requires_user_action': False,
            'page_title': '店小秘可见会话',
            'page_url': page_url,
            'screenshot_url': None,
            'browser_visible': not self._is_headless(),
            'browser_session_id': browser_session_id,
            'account_ref': account_ref,
            'updated_at': now_iso(),
        }
        self._write_state(state)
        return state

    def check_visible_login_state(self) -> dict[str, Any]:
        home_url = 'https://www.dianxiaomi.com/web/home'
        try:
            page = self._ensure_page_with_cookies()
            self._trace_workflow_event(
                'visible_login_check:start',
                url=home_url,
                current_url=getattr(page, 'url', None),
                human_step='检查执行浏览器登录态',
            )
            self._goto_sterile(page, home_url, wait_until='domcontentloaded', timeout=45000)
            self._force_foreground_dxm_window()
            page.wait_for_timeout(3000)
            login_check = self._inspect_visible_login_state(page)
            visible_logged_in = login_check.get('logged_in') is True
            self._trace_workflow_event(
                'visible_login_check:done',
                url=getattr(page, 'url', None),
                visible_logged_in=visible_logged_in,
                body_excerpt=login_check.get('body_excerpt'),
                human_step='执行浏览器登录态检查完成',
            )
            screenshot_url = None
            page_title = '店小秘登录态检查'
            unreadable_home = login_check.get('reason') == 'home_body_empty'
            if visible_logged_in:
                self._persist_visible_browser_cookies()
                reader_status = self._visible_reader_session_status()
                reader_ready = reader_status['reader_ready'] is True
                state = {
                    'ok': reader_ready,
                    'stage': 'login_success',
                    'reason_code': reader_status['reason_code'],
                    'logged_in': True,
                    'reader_ready': reader_ready,
                    'label': '已登录且 Reader 就绪' if reader_ready else '已登录，但 Reader 未就绪',
                    'message': (
                        '执行浏览器已登录店小秘，店铺与草稿 Reader 可以立即复用。'
                        if reader_ready
                        else '执行浏览器已登录店小秘，但当前只读会话仍不可复用。'
                    ),
                    'next_action': (
                        '进入采集箱选品；当前阶段不会保存或发布。'
                        if reader_ready
                        else '保留当前窗口并重新检测，不要另开第二套登录脚本。'
                    ),
                    'requires_user_action': not reader_ready,
                    'page_title': page_title or '店小秘首页',
                    'page_url': getattr(page, 'url', None) or home_url,
                    'screenshot_url': screenshot_url,
                    'browser_visible': not self._is_headless(),
                    'visible_logged_in': True,
                    'login_check': login_check,
                    'updated_at': now_iso(),
                }
            elif unreadable_home:
                state = {
                    'ok': False,
                    'stage': 'login_page_unreadable',
                    'reason_code': 'DXM_PAGE_NOT_READY',
                    'logged_in': False,
                    'reader_ready': False,
                    'label': '店小秘页面未加载完成',
                    'message': '执行浏览器已打开店小秘首页，但页面内容为空，无法确认登录状态。',
                    'next_action': '请在真实浏览器刷新页面；如果仍为空，重启真实浏览器执行器后重新检测。',
                    'requires_user_action': True,
                    'page_title': page_title or '店小秘首页',
                    'page_url': getattr(page, 'url', None) or home_url,
                    'screenshot_url': screenshot_url,
                    'browser_visible': not self._is_headless(),
                    'visible_logged_in': False,
                    'login_check': login_check,
                    'updated_at': now_iso(),
                }
            else:
                state = {
                    'ok': False,
                    'stage': 'login_failed',
                    'reason_code': 'LOGIN_REQUIRED',
                    'logged_in': False,
                    'reader_ready': False,
                    'label': '执行浏览器未登录',
                    'message': '执行浏览器还没有登录店小秘；请在打开的真实浏览器完成登录后再检测。',
                    'next_action': '点击打开真实登录页，或在当前浏览器内完成登录后重新检测。',
                    'requires_user_action': True,
                    'page_title': page_title or '店小秘官网登录页',
                    'page_url': getattr(page, 'url', None) or home_url,
                    'screenshot_url': screenshot_url,
                    'browser_visible': not self._is_headless(),
                    'visible_logged_in': False,
                    'login_check': login_check,
                    'updated_at': now_iso(),
                }
            self._write_state(state)
            return state
        except Exception as exc:
            state = self._error_state(
                stage='login_failed',
                label='执行浏览器检查失败',
                message=f'检查执行浏览器登录态失败：{exc}',
                next_action='真实浏览器窗口会保留；请检查页面后重新检测。',
                reason_code='VISIBLE_SESSION_CHECK_FAILED',
            )
            state['browser_visible'] = not self._is_headless()
            self._keep_visible_browser_for_recovery(state)
            self._write_state(state)
            return state

    def navigate_post_login(self, target: str) -> dict[str, Any]:
        if target not in WORKFLOW_TARGETS:
            state = self._error_state(
                stage='workflow_navigation_failed',
                label='无效目标',
                message=f'不支持的业务导航目标：{target}',
                next_action='请改为 product、data_acquisition 或 draft_box。',
            )
            self._write_state(state)
            return state
        try:
            result = self._navigate_in_session(target)
        except Exception as exc:
            state = self._error_state(
                stage='workflow_navigation_failed',
                label='导航失败',
                message=f'进入业务页失败：{exc}',
                next_action='确认登录态有效，必要时在真实浏览器内修正页面后再试。',
            )
            self._keep_visible_browser_for_recovery(state)
            self._write_state(state)
            return state

        config = WORKFLOW_TARGETS[target]
        state = {
            'ok': True,
            'stage': 'workflow_navigation',
            'label': config['label'],
            'message': config['message'],
            'next_action': f"真实浏览器窗口会保留；{config['next_action']}",
            'requires_user_action': False,
            'page_title': result.get('page_title') or config['label'],
            'page_url': result.get('page_url') or config['url'],
            'screenshot_url': result.get('screenshot_url'),
            'browser_visible': not self._is_headless(),
            'updated_at': now_iso(),
            'current_nav': target,
            'wait_result': result.get('wait_result'),
            'navigation_result': dict(result),
            'dismissed_blocking_modals': result.get('dismissed_blocking_modals'),
            'dismissed_blocking_modals_trace': result.get('dismissed_blocking_modals_trace') or [],
        }
        self._write_state(state)
        return state

    def read_draft_shops(self) -> dict[str, Any]:
        """Read userInfo.shopMap from the current visible authenticated session."""

        _page, context, browser_session_id = self._draft_reader_session()
        payload, account_ref = self._read_authenticated_user_info(
            context,
            browser_session_id,
        )
        return {
            'browser_session_id': browser_session_id,
            'account_ref': account_ref,
            'payload': payload,
        }

    def read_draft_page(
        self,
        *,
        shop_id: str,
        page_no: int,
        page_size: int,
    ) -> dict[str, Any]:
        """Read one draft-only page without navigating or exporting cookies."""

        normalized_shop_id = str(shop_id or '')
        if normalized_shop_id != '-1':
            if (
                normalized_shop_id != normalized_shop_id.strip()
                or not normalized_shop_id.isdecimal()
                or int(normalized_shop_id) <= 0
                or str(int(normalized_shop_id)) != normalized_shop_id
            ):
                raise DxmDraftReaderError(
                    'SHOP_FILTER_INVALID',
                    '店铺筛选身份无效，已停止读取。',
                )
        if (
            isinstance(page_no, bool)
            or not isinstance(page_no, int)
            or not 1 <= page_no <= 100_000
            or isinstance(page_size, bool)
            or not isinstance(page_size, int)
            or not 1 <= page_size <= 100
        ):
            raise DxmDraftReaderError(
                'PAGINATION_REQUEST_INVALID',
                '草稿列表分页请求超出允许范围。',
            )

        _page, context, browser_session_id = self._draft_reader_session()
        _user_info, account_ref = self._read_authenticated_user_info(
            context,
            browser_session_id,
        )
        form = {
            'pageNo': str(page_no),
            'pageSize': str(page_size),
            'total': '0',
            'searchType': '0',
            'searchValue': '',
            'shopId': normalized_shop_id,
            'dxmState': 'draft',
            'dxmOfflineState': '',
        }
        method = 'POST'
        url = 'https://www.dianxiaomi.com/api/smtProduct/pageList.json'
        self._assert_draft_reader_allowlisted(method, url, form=form)
        try:
            response = context.request.post(
                url,
                form=form,
                timeout=15_000,
            )
        except Exception as exc:
            raise DxmDraftReaderError(
                'DXM_PAGE_READ_FAILED',
                '当前真实店小秘会话的草稿列表读取失败。',
            ) from exc
        payload = self._validated_draft_reader_response(
            response,
            label='草稿列表',
            expected_browser_session_id=browser_session_id,
        )
        return {
            'browser_session_id': browser_session_id,
            'account_ref': account_ref,
            'payload': payload,
        }

    def read_e2_plan_scope(
        self,
        *,
        shop_id: str,
        category_ids: list[str],
    ) -> dict[str, Any]:
        """Read E2 template references and category schemas from this browser only."""

        normalized_shop_id = self._positive_reader_id(shop_id, label='店铺')
        normalized_category_ids = [
            self._positive_reader_id(value, label='类目')
            for value in category_ids
        ]
        if (
            not normalized_category_ids
            or len(normalized_category_ids) > 50
            or len(set(normalized_category_ids)) != len(normalized_category_ids)
        ):
            raise DxmDraftReaderError(
                'DXM_PLAN_SCOPE_INVALID',
                'E2 类目作用域必须包含 1–50 个不重复类目。',
            )
        _page, context, browser_session_id = self._draft_reader_session()
        user_info, account_ref = self._read_authenticated_user_info(
            context,
            browser_session_id,
        )
        if not self._user_info_contains_shop(user_info, normalized_shop_id):
            raise DxmDraftReaderError(
                'DXM_TEMPLATE_SCOPE_CONFLICT',
                '请求店铺不在当前登录账号的 shopMap 中。',
            )

        records: list[dict[str, Any]] = []
        records.extend(
            self._read_e2_product_templates(
                context,
                browser_session_id=browser_session_id,
                shop_id=normalized_shop_id,
                category_ids=set(normalized_category_ids),
            )
        )
        records.extend(
            self._read_e2_attribute_templates(
                context,
                browser_session_id=browser_session_id,
                shop_id=normalized_shop_id,
                category_ids=set(normalized_category_ids),
            )
        )
        shop_templates = self._e2_post_data(
            context,
            browser_session_id=browser_session_id,
            url='https://www.dianxiaomi.com/api/smtShopInfoSync/list.json',
            form={'shopId': normalized_shop_id},
            label='店铺模板',
        )
        if not isinstance(shop_templates, Mapping):
            raise DxmDraftReaderError(
                'DXM_TEMPLATE_RESPONSE_INVALID',
                '店铺模板只读回包 data 结构无效。',
            )
        records.extend(
            self._e2_named_template_records(
                shop_templates.get('freightTemplateList'),
                ref_type='freight',
                id_keys=('templateId',),
                name_keys=('templateName',),
                shop_id=normalized_shop_id,
                category_id=None,
                source_api='/api/smtShopInfoSync/list.json',
            )
        )
        records.extend(
            self._e2_named_template_records(
                shop_templates.get('promiseTemplateList'),
                ref_type='service',
                id_keys=('templateId',),
                name_keys=('templateName',),
                shop_id=normalized_shop_id,
                category_id=None,
                source_api='/api/smtShopInfoSync/list.json',
            )
        )

        category_schemas: dict[str, dict[str, Any]] = {}
        for category_id in normalized_category_ids:
            common_form = {
                'shopId': normalized_shop_id,
                'categoryId': category_id,
            }
            variation_data = self._e2_post_data(
                context,
                browser_session_id=browser_session_id,
                url=(
                    'https://www.dianxiaomi.com/api/'
                    'variationTemplate/com/smt/getNameListByCategory.json'
                ),
                form=common_form,
                label='类目变种模板',
                allow_null=True,
            )
            variation_list = self._e2_optional_list(
                variation_data,
                keys=('list', 'variationTemplateList', 'nameList'),
            )
            records.extend(
                self._e2_named_template_records(
                    variation_list,
                    ref_type='variation',
                    id_keys=('idStr', 'id', 'templateId'),
                    name_keys=('templateName', 'name'),
                    shop_id=normalized_shop_id,
                    category_id=category_id,
                    source_api=(
                        '/api/variationTemplate/com/smt/'
                        'getNameListByCategory.json'
                    ),
                )
            )

            size_data = self._e2_post_data(
                context,
                browser_session_id=browser_session_id,
                url='https://www.dianxiaomi.com/api/smtShopInfoSync/sizeChartList.json',
                form=common_form,
                label='类目尺码表',
            )
            if not isinstance(size_data, Mapping):
                raise DxmDraftReaderError(
                    'DXM_TEMPLATE_RESPONSE_INVALID',
                    '类目尺码表只读回包 data 结构无效。',
                )
            records.extend(
                self._e2_named_template_records(
                    size_data.get('sizeList'),
                    ref_type='size',
                    id_keys=('idStr', 'id', 'templateId', 'sizeId'),
                    name_keys=('templateName', 'name', 'sizeName'),
                    shop_id=normalized_shop_id,
                    category_id=category_id,
                    source_api='/api/smtShopInfoSync/sizeChartList.json',
                )
            )

            attribute_schema_data = self._e2_post_data(
                context,
                browser_session_id=browser_session_id,
                url='https://www.dianxiaomi.com/api/smtCategory/attributeList.json',
                form={'categoryId': category_id},
                label='类目属性 Schema',
            )
            attribute_schema_data = self._read_e2_child_attribute_cases(
                context,
                browser_session_id=browser_session_id,
                category_id=category_id,
                attribute_schema_data=attribute_schema_data,
            )
            category_schemas[category_id] = self._e2_category_schema(
                attribute_schema_data,
                category_id=category_id,
            )

        records = [
            self._e2_schema_normalized_template_record(
                record,
                category_schemas=category_schemas,
            )
            for record in records
        ]
        identities: dict[tuple[str, str, str, str | None], dict[str, Any]] = {}
        for record in records:
            identity = (
                record['ref_type'],
                record['dxm_template_id'],
                record['shop_id'],
                record['category_id'],
            )
            previous = identities.get(identity)
            if previous is not None and previous != record:
                raise DxmDraftReaderError(
                    'DXM_TEMPLATE_IDENTITY_CONFLICT',
                    '同一模板身份返回了冲突内容，已停止同步。',
                )
            identities[identity] = record
        _ending_user_info, ending_account_ref = self._read_authenticated_user_info(
            context,
            browser_session_id,
        )
        if ending_account_ref != account_ref:
            raise DxmDraftReaderError(
                'AUTH_ACCOUNT_MISMATCH',
                'E2 只读同步期间登录账号已变化，已丢弃全部结果。',
            )
        if self.browser_session_id() != browser_session_id:
            raise DxmDraftReaderError(
                'BROWSER_SESSION_MISMATCH',
                'E2 只读同步期间真实浏览器会话已变化。',
            )
        return {
            'browser_session_id': browser_session_id,
            'account_ref': account_ref,
            'payload': {
                'template_records': list(identities.values()),
                'category_schemas': category_schemas,
            },
        }

    def read_e2_product_details(
        self,
        *,
        shop_id: str,
        product_ids: list[str],
    ) -> dict[str, Any]:
        """Read current edit.json values for the confirmed E2 draft scope."""

        normalized_shop_id = self._positive_reader_id(shop_id, label='店铺')
        if not isinstance(product_ids, list) or not 3 <= len(product_ids) <= 100:
            raise DxmDraftReaderError(
                'PLAN_ITEM_COUNT_INVALID',
                'E2 编辑页当前值读取必须绑定 3–100 件当次草稿。',
            )
        normalized_product_ids = [
            self._positive_reader_id(value, label='商品')
            for value in product_ids
        ]
        if len(set(normalized_product_ids)) != len(normalized_product_ids):
            raise DxmDraftReaderError(
                'PLAN_PRODUCT_DUPLICATE',
                'E2 编辑页当前值商品 ID 必须唯一。',
            )

        _page, context, browser_session_id = self._draft_reader_session()
        user_info, account_ref = self._read_authenticated_user_info(
            context,
            browser_session_id,
        )
        if not self._user_info_contains_shop(user_info, normalized_shop_id):
            raise DxmDraftReaderError(
                'PLAN_SCOPE_CONFLICT',
                '请求店铺不在当前登录账号的 shopMap 中。',
            )

        method = 'GET'
        url = 'https://www.dianxiaomi.com/api/smtProduct/edit.json'
        products: list[dict[str, Any]] = []
        for product_id in normalized_product_ids:
            self._assert_e2_product_detail_read_allowlisted(
                method,
                url,
                params={'id': product_id},
            )
            try:
                response = context.request.get(
                    url,
                    params={'id': product_id},
                    timeout=15_000,
                )
            except Exception as exc:
                raise DxmDraftReaderError(
                    'DXM_PRODUCT_DETAIL_READ_FAILED',
                    '当前真实店小秘会话的编辑页商品当前值读取失败。',
                ) from exc
            payload = self._validated_draft_reader_response(
                response,
                label='编辑页商品当前值',
                expected_browser_session_id=browser_session_id,
            )
            code = payload.get('code')
            if not (
                (type(code) is int and code == 0)
                or (type(code) is str and code == '0')
            ):
                raise DxmDraftReaderError(
                    'DXM_PRODUCT_DETAIL_READ_REJECTED',
                    '店小秘编辑页商品当前值接口未返回严格成功状态。',
                )
            data = payload.get('data')
            product = data.get('product') if isinstance(data, Mapping) else None
            if not isinstance(product, Mapping):
                raise DxmDraftReaderError(
                    'DXM_PRODUCT_DETAIL_RESPONSE_INVALID',
                    '店小秘编辑页商品当前值回包缺少 product。',
                )
            products.append(dict(product))

        _ending_user_info, ending_account_ref = self._read_authenticated_user_info(
            context,
            browser_session_id,
        )
        if ending_account_ref != account_ref:
            raise DxmDraftReaderError(
                'AUTH_ACCOUNT_MISMATCH',
                '编辑页当前值读取期间登录账号已变化，已丢弃全部结果。',
            )
        if self.browser_session_id() != browser_session_id:
            raise DxmDraftReaderError(
                'BROWSER_SESSION_MISMATCH',
                '编辑页当前值读取期间真实浏览器会话已变化。',
            )
        return {
            'browser_session_id': browser_session_id,
            'account_ref': account_ref,
            'payload': {'products': products},
        }

    @staticmethod
    def _assert_e2_product_detail_read_allowlisted(
        method: str,
        url: str,
        *,
        params: Mapping[str, str],
    ) -> None:
        if (
            (method, url) not in DXM_E2_PLAN_READ_ALLOWLIST
            or method != 'GET'
            or set(params) != {'id'}
        ):
            raise DxmDraftReaderError(
                'DXM_PLAN_READ_ALLOWLIST_VIOLATION',
                'E2 编辑页当前值请求不在冻结的只读白名单内。',
            )
        product_id = str(params.get('id') or '')
        if (
            not product_id.isdecimal()
            or int(product_id) <= 0
            or str(int(product_id)) != product_id
        ):
            raise DxmDraftReaderError(
                'DXM_PLAN_READ_ALLOWLIST_VIOLATION',
                'E2 编辑页当前值请求包含无效商品 ID。',
            )

    def _read_e2_product_templates(
        self,
        context: BrowserContext,
        *,
        browser_session_id: str,
        shop_id: str,
        category_ids: set[str],
    ) -> list[dict[str, Any]]:
        records: list[dict[str, Any]] = []
        page_no = 1
        while True:
            data = self._e2_post_data(
                context,
                browser_session_id=browser_session_id,
                url='https://www.dianxiaomi.com/api/userTemplate/pageList.json',
                form={
                    'platform': 'smt',
                    'shopId': shop_id,
                    'pageNo': str(page_no),
                    'pageSize': '50',
                    'total': '0',
                    'searchType': '1',
                    'searchValue': '',
                },
                label='产品模板',
            )
            if not isinstance(data, Mapping) or not isinstance(data.get('page'), Mapping):
                raise DxmDraftReaderError(
                    'DXM_TEMPLATE_RESPONSE_INVALID',
                    '产品模板只读回包缺少分页 data.page。',
                )
            page = data['page']
            observed_page_no = self._strict_reader_nonnegative_int(
                page.get('pageNo'),
                label='产品模板 pageNo',
            )
            page_size = self._strict_reader_nonnegative_int(
                page.get('pageSize'),
                label='产品模板 pageSize',
            )
            total_pages = self._strict_reader_nonnegative_int(
                page.get('totalPage'),
                label='产品模板 totalPage',
            )
            raw_items = page.get('list')
            if (
                observed_page_no != page_no
                or page_size != 50
                or not isinstance(raw_items, list)
                or total_pages < 0
                or total_pages > 100
                or (total_pages == 0 and (page_no != 1 or raw_items))
                or (total_pages > 0 and not 1 <= page_no <= total_pages)
            ):
                raise DxmDraftReaderError(
                    'DXM_TEMPLATE_PAGINATION_INVALID',
                    '产品模板分页回包不闭合。',
                )
            for raw in raw_items:
                if not isinstance(raw, Mapping):
                    raise DxmDraftReaderError(
                        'DXM_TEMPLATE_RESPONSE_INVALID',
                        '产品模板列表存在无效对象。',
                    )
                record_shop_id = self._positive_reader_id(
                    raw.get('shopId'),
                    label='产品模板店铺',
                )
                if record_shop_id != shop_id:
                    raise DxmDraftReaderError(
                        'DXM_TEMPLATE_SCOPE_CONFLICT',
                        '产品模板属于另一个店铺。',
                    )
                raw_category_id = raw.get('categoryId') or raw.get('nodePathId')
                category_id = (
                    None
                    if raw_category_id in (None, '')
                    else self._positive_reader_id(
                        raw_category_id,
                        label='产品模板类目',
                    )
                )
                if category_id is not None and category_id not in category_ids:
                    continue
                records.append(
                    self._e2_template_record(
                        raw,
                        ref_type='product',
                        id_keys=('idStr', 'id'),
                        name_keys=('name', 'templateName'),
                        shop_id=shop_id,
                        category_id=category_id,
                        source_api='/api/userTemplate/pageList.json',
                    )
                )
            if total_pages in (0, page_no):
                return records
            page_no += 1

    def _read_e2_attribute_templates(
        self,
        context: BrowserContext,
        *,
        browser_session_id: str,
        shop_id: str,
        category_ids: set[str],
    ) -> list[dict[str, Any]]:
        records: list[dict[str, Any]] = []
